  // Removing a member unassigns every live issue they held, one event per issue.
  it("unassigns live issues and leaves archived ones untouched on removal", async () => {
    const tenant = await createTenant("member-remove-unassigns", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("fixture member missing");

    const liveIssue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Live and assigned",
        assigneeId: tenant.userIds.viewer,
      }),
    );
    const archivedIssue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Archived and assigned",
        assigneeId: tenant.userIds.viewer,
      }),
    );
    await issueService.archiveIssue(tenant.actors.owner, tenant.org.id, archivedIssue.id);

    const seen: unknown[] = [];
    const off = subscribe("issue.unassigned", (payload) => seen.push(payload));

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    off();

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      issueId: liveIssue.id,
      previousAssigneeId: tenant.userIds.viewer,
    });

    const updatedLive = await issueRepo.findIssueById(tenant.org.id, liveIssue.id);
    const updatedArchived = await issueRepo.findIssueById(
      tenant.org.id,
      archivedIssue.id,
    );
    expect(updatedLive?.assigneeId).toBeNull();
    expect(updatedArchived?.assigneeId).toBe(tenant.userIds.viewer);
  });
});

